package mvcckv

// Vacuum garbage-collects obsolete versions.
//
// A version is reclaimable when no active (or future) transaction can ever
// observe it as the newest visible version. The active-transaction watermark
// is the smallest snapshot id among in-flight transactions:
//
//   - every version with createdTxID >= watermark is retained (it may be the
//     newest visible version for some active snapshot);
//   - among the older tail, only the single newest live version is retained
//     (older snapshots may still land on it); any superseded versions and all
//     tombstones are reclaimed;
//   - if nothing remains but a tombstone, the whole key index is removed.
func (e *Engine) Vacuum() error {
	e.lifecycleMu.RLock()
	closed := e.closed.Load()
	e.lifecycleMu.RUnlock()
	if closed {
		return ErrEngineClosed
	}

	e.indexMu.Lock()
	defer e.indexMu.Unlock()

	wm := e.watermarkLocked()

	for key, chain := range e.data {
		kept := make([]*version, 0, len(chain))
		passedWatermark := false

		for _, v := range chain { // newest first
			if v.createdTxID >= wm {
				kept = append(kept, v)
				continue
			}
			// Newest version below the watermark: retain only while it is a
			// live (non-tombstone) value that an older snapshot could read.
			if !passedWatermark && !v.isDeleted {
				kept = append(kept, v)
			}
			passedWatermark = true
		}

		switch {
		case len(kept) == 0:
			delete(e.data, key)
		case kept[0].isDeleted && kept[0].createdTxID < wm:
			// The retained newest version is itself an old tombstone.
			delete(e.data, key)
		default:
			e.data[key] = kept
		}
	}

	return nil
}

